exercise.solution:
fn main() {
    let squares: Vec<u32> = (1..=20).filter(|n| n % 2 == 0).map(|n| n * n).collect();
    let joined: Vec<String> = squares.iter().map(|s| s.to_string()).collect();
    println!("{}", joined.join(", "));
}
